interface DebounceOptions {
  /** Invoke on the leading edge of the wait interval. Default: false */
  leading?: boolean;
  /** Invoke on the trailing edge of the wait interval. Default: true */
  trailing?: boolean;
  /** Maximum time func is allowed to be delayed before it's invoked. */
  maxWait?: number;
}

interface DebouncedFunction<T extends (...args: any[]) => any> {
  (...args: Parameters<T>): ReturnType<T> | undefined;
  /** Cancel any pending invocation. */
  cancel(): void;
  /** Immediately invoke pending invocation, if any. */
  flush(): ReturnType<T> | undefined;
  /** Returns true if there is a pending invocation. */
  pending(): boolean;
}

export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number,
  options: DebounceOptions = {}
): DebouncedFunction<T> {
  const leading = options.leading ?? false;
  const trailing = options.trailing ?? true;
  const hasMaxWait = options.maxWait !== undefined;
  const maxWait = hasMaxWait ? Math.max(options.maxWait!, wait) : 0;

  let lastArgs: Parameters<T> | undefined;
  let lastThis: unknown;
  let result: ReturnType<T> | undefined;
  let timerId: ReturnType<typeof setTimeout> | undefined;
  let lastCallTime: number | undefined;
  let lastInvokeTime = 0;

  function invokeFunc(time: number): ReturnType<T> | undefined {
    const args = lastArgs!;
    const thisArg = lastThis;
    lastArgs = lastThis = undefined;
    lastInvokeTime = time;
    result = func.apply(thisArg, args);
    return result;
