type DebounceOptions = {
  leading?: boolean;
  trailing?: boolean;
};

function debounce<Args extends unknown[]>(
  fn: (...args: Args) => void,
  delay: number,
  { leading = false, trailing = true }: DebounceOptions = {},
): (...args: Args) => void {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let lastArgs: Args | undefined;
  let lastThis: unknown;

  return function (this: unknown, ...args: Args): void {
    lastArgs = args;
    lastThis = this;

    const isFirstCall = timer === undefined;

    if (timer !== undefined) {
      clearTimeout(timer);
    }

    if (leading && isFirstCall) {
      fn.apply(lastThis, lastArgs);
      // The call has already been handled; don't repeat it on the trailing edge
      // unless another call arrives during the wait period.
      lastArgs = undefined;
    }

    timer = setTimeout(() => {
      timer = undefined;

      if (trailing && lastArgs !== undefined) {
        fn.apply(lastThis, lastArgs);
      }

      lastArgs = undefined;
      lastThis = undefined;
    }, delay);
  };
}
```

Each call resets the timer, so `fn` runs only after calls have stopped for `delay` milliseconds.

- **Leading** runs `fn` immediately on the first call in a burst. Useful when the user should get immediate feedback, such as starting a search or responding to the first click.
- **Trailing** runs `fn` after the burst ends, using the most recent call’s arguments. Useful for work that should reflect the final input, such as filtering text or saving edits.
- You can enable both to run once at the start and again after the burst, if there were later calls. With neither enabled, the function never runs.

