package main

import (
	"context"
	"errors"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"
)

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ok\n"))
	})

	server := &http.Server{
		Addr:              ":8080",
		Handler:           requestLogging(mux),
		ReadHeaderTimeout: 5 * time.Second,
	}

	// Start serving in the background so the main goroutine can wait for a
	// termination signal.
	serveErr := make(chan error, 1)
	go func() {
		log.Printf("listening on %s", server.Addr)
		serveErr <- server.ListenAndServe()
	}()

	// Wait for SIGINT or SIGTERM, unless the server exits unexpectedly.
	signals := make(chan os.Signal, 1)
	signal.Notify(signals, os.Interrupt, syscall.SIGTERM)
	defer signal.Stop(signals)

	select {
	case sig := <-signals:
		log.Printf("received %s; beginning graceful shutdown", sig)
	case err := <-serveErr:
		if !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("HTTP server failed: %v", err)
		}
		return
	}

	// Stop accepting new connections and wait for active requests to finish.
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := server.Shutdown(ctx); err != nil {
		log.Printf("graceful shutdown failed: %v; forcing close", err)
		if closeErr := server.Close(); closeErr != nil {
			log.Printf("forced close failed: %v", closeErr)
		}
	}

	// Collect the result from ListenAndServe.
	if err := <-serveErr; err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Printf("HTTP server exited with error: %v", err)
	}

	log.Println("server stopped")
}

func requestLogging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start))
	})
}
```

### Shutdown sequence

1. The server runs in a goroutine while the main goroutine waits for `SIGTERM` or `SIGINT`.
2. When a signal arrives, `Server.Shutdown` stops the server from accepting new connections and waits for in-flight requests to finish.
3. Shutdown is limited to 10 seconds. If requests are still active when the deadline expires, `Server.Close` forcefully closes connections.
4. The program waits for the serving goroutine to exit, then terminates.

Run it with `go run .` and check the endpoint using `curl http://localhost:8080/health`.

Here's a compact, dependency-free event emitter with `on`, `off`, `once`, and `emit`.

## Implementation

```javascript
class EventEmitter {
  constructor() {
    // Map<eventName, Array<listener>>
    this._events = new Map();
  }

  /**
   * Register a listener for an event.
   * Returns `this` so calls can be chained.
   */
  on(event, listener) {
    if (typeof listener !== 'function') {
      throw new TypeError('listener must be a function');
    }
    if (!this._events.has(event)) {
      this._events.set(event, []);
    }
    this._events.get(event).push(listener);
    return this;
  }

  /**
   * Remove a specific listener for an event.
   * Returns `this` so calls can be chained.
   */
  off(event, listener) {
    const listeners = this._events.get(event);
    if (!listeners) return this;

    const index = listeners.indexOf(listener);
    if (index !== -1) {
      listeners.splice(index, 1);
    }
    if (listeners.length === 0) {
      this._events.delete(event);
    }
    return this;
  }

  /**
   * Register a listener that runs at most once.
   * Returns `this` so calls can be chained.
   */
  once(event, listener) {
    if (typeof listener !== 'function') {
      throw new TypeError('listener must be a function');
    }

    const wrapper = (...args) => {
      this.off(event, wrapper);   // remove before calling
      listener.apply(this, args); // preserve `this` semantics
    };
    wrapper.listener = listener;  // so off(event, original) works too

    return this.on(event, wrapper);
  }

  /**
   * Invoke all listeners for an event with the given arguments.
   * Returns true if there were listeners, false otherwise.
   */
  emit(event, ...args) {
    const listeners = this._events.get(event);
    if (!listeners || listeners.length === 0) return false;

    // Copy the array so listeners added/removed during emit
    // don't affect this dispatch.
    for (const listener of [...listeners]) {
      listener.apply(this, args);
    }
    return true;
  }
}
```

I also made `off` aware of `once` wrappers. Since `once` stores the original listener on `wrapper.listener`, you can unsubscribe with the original function. Adding that check to `off` makes this work:

```javascript
off(event, listener) {
  const listeners = this._events.get(event);
  if (!listeners) return this;

  const index = listeners.findIndex(
    (l) => l === listener || l.listener === listener
  );
  if (index !== -1) {
    listeners.splice(index, 1);
  }
  if (listeners.length === 0) {
    this._events.delete(event);
  }
  return this;
}
```

Use this version in place of the earlier `off`.

