class EventEmitter {
  constructor() {
    this.events = new Map();
  }

  on(event, listener) {
    if (typeof listener !== "function") {
      throw new TypeError("listener must be a function");
    }

    const listeners = this.events.get(event) ?? [];
    listeners.push(listener);
    this.events.set(event, listeners);

    // Returning an unsubscribe function is convenient, though optional.
    return () => this.off(event, listener);
  }

  off(event, listener) {
    const listeners = this.events.get(event);
    if (!listeners) return;

    const remaining = listeners.filter((item) => item !== listener);
    if (remaining.length) {
      this.events.set(event, remaining);
    } else {
      this.events.delete(event);
    }
  }

  once(event, listener) {
    const wrapper = (...args) => {
      // Remove before calling so it still runs only once if it emits itself.
      this.off(event, wrapper);
      listener(...args);
    };

    return this.on(event, wrapper);
  }

  emit(event, ...args) {
    const listeners = this.events.get(event);
    if (!listeners) return false;

    // Copy the list so changes made during emission don't affect this pass.
    for (const listener of [...listeners]) {
      listener(...args);
    }

    return true;
  }
}
```

### Example

```js
const emitter = new EventEmitter();

const onMessage = (message) => {
  console.log("Message:", message);
};

emitter.on("message", onMessage);
emitter.once("ready", () => console.log("Ready once"));

emitter.emit("message", "Hello"); // Message: Hello

emitter.emit("ready"); // Ready once
emitter.emit("ready"); // Nothing

emitter.off("message", onMessage);
emitter.emit("message", "This won't be printed");
```

`once` registers a wrapper around the listener. When the event fires, the wrapper removes itself before calling the original listener. Removing it first ensures it cannot run again—even if the listener synchronously emits the same event.

Here's a generic, owned binary search tree in Rust with `insert`, `contains`, and in-order traversal, followed by an explanation of the ownership decisions.

