#[derive(Debug)]
struct Node<T> {
    value: T,
    left: Option<Box<Node<T>>>,
    right: Option<Box<Node<T>>>,
}

#[derive(Debug)]
pub struct Bst<T> {
    root: Option<Box<Node<T>>>,
    len: usize,
}

impl<T: Ord> Bst<T> {
    pub fn new() -> Self {
        Bst { root: None, len: 0 }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Inserts a value. Returns `false` if the value was already present
    /// (the tree is unchanged in that case).
    pub fn insert(&mut self, value: T) -> bool {
        // `cursor` walks down the tree, always holding a mutable reference
        // to the `Option` slot where the next node should go.
        let mut cursor = &mut self.root;

        while let Some(node) = cursor {
            if value < node.value {
                cursor = &mut node.left;
            } else if value > node.value {
                cursor = &mut node.right;
            } else {
                return false; // duplicate
            }
        }

        *cursor = Some(Box::new(Node {
            value,
            left: None,
            right: None,
        }));
        self.len += 1;
        true
    }

    /// Returns `true` if the tree contains `value`.
    pub fn contains(&self, value: &T) -> bool {
        let mut cursor = &self.root;
        while let Some(node) = cursor {
            match value.cmp(&node.value) {
                std::cmp::Ordering::Less => cursor = &node.left,
                std::cmp::Ordering::Greater => cursor = &node.right,
                std::cmp::Ordering::Equal => return true,
            }
        }
        false
    }

    /// Returns an iterator yielding references in ascending (in-order) order.
    pub fn iter(&self) -> InOrderIter<'_, T> {
        let mut iter = InOrderIter { stack: Vec::new() };
        iter.push_left(self.root.as_deref());
        iter
    }
}

impl<T: Ord> Default for Bst<T> {
    fn default() -> Self {
        Self::new()
    }
}

/// Iterative in-order traversal using an explicit stack.
/// Holds only shared references, so it borrows the tree immutably.
pub struct InOrderIter<'a, T> {
    stack: Vec<&'a Node<T>>,
}

impl<'a, T> InOrderIter<'a, T> {
    fn push_left(&mut self, mut node: Option<&'a Node<T>>) {
        while let Some(n) = node {
            self.stack.push(n);
            node = n.left.as_deref();
        }
    }
}

