use std::cmp::Ordering;

#[derive(Debug)]
struct Node<T> {
    value: T,
    left: Option<Box<Node<T>>>,
    right: Option<Box<Node<T>>>,
}

#[derive(Debug, Default)]
pub struct BinarySearchTree<T> {
    root: Option<Box<Node<T>>>,
}

impl<T: Ord> BinarySearchTree<T> {
    pub fn new() -> Self {
        Self { root: None }
    }

    pub fn insert(&mut self, value: T) {
        let mut link = &mut self.root;

        loop {
            match link {
                None => {
                    *link = Some(Box::new(Node {
                        value,
                        left: None,
                        right: None,
                    }));
                    return;
                }
                Some(node) => match value.cmp(&node.value) {
                    Ordering::Less => link = &mut node.left,
                    Ordering::Greater => link = &mut node.right,
                    Ordering::Equal => return, // Ignore duplicates.
                },
            }
        }
    }

    pub fn contains(&self, value: &T) -> bool {
        let mut current = self.root.as_deref();

        while let Some(node) = current {
            match value.cmp(&node.value) {
                Ordering::Less => current = node.left.as_deref(),
                Ordering::Greater => current = node.right.as_deref(),
                Ordering::Equal => return true,
            }
        }

        false
    }

    /// Visits values in ascending order.
    pub fn inorder<F>(&self, mut visit: F)
    where
        F: FnMut(&T),
    {
        fn walk<T, F>(node: Option<&Node<T>>, visit: &mut F)
        where
            F: FnMut(&T),
        {
            if let Some(node) = node {
                walk(node.left.as_deref(), visit);
                visit(&node.value);
                walk(node.right.as_deref(), visit);
            }
        }

        walk(self.root.as_deref(), &mut visit);
    }
}

fn main() {
    let mut tree = BinarySearchTree::new();
    tree.insert(5);
    tree.insert(2);
    tree.insert(8);
    tree.insert(5); // Duplicate is ignored.

    assert!(tree.contains(&2));
    assert!(!tree.contains(&7));

    let mut sorted = Vec::new();
    tree.inorder(|value| sorted.push(*value));
    assert_eq!(sorted, vec![2, 5, 8]);
}
```

### Ownership choices

- Each node is owned by its parent through `Option<Box<Node<T>>>`. `Box` gives nodes a fixed-size, heap-allocated representation, allowing the recursive tree structure.
- The root owns the entire tree. When the tree is dropped, Rust recursively drops its child nodes automatically; no manual memory management or reference counting is needed.
- `insert` takes `T` by value, transferring ownership of the inserted value into the tree. Equal values are discarded, so this implementation does not store duplicates.
- `contains` and `inorder` borrow values rather than taking ownership. The traversal callback receives `&T`, so it can inspect values without removing or cloning them.

This is a simple, unbalanced BST: its operations take **O(h)** time, where *h* is the tree height. In the worst case, the height can be **O(n)**.
